INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('a3c1281b-930a-5a4c-92c5-3ede224a5c1c', '4d881b9d-6971-54d8-a552-781f2ae6497e', 'Are the clay diyas and wicks sufficient for a complete Chaturthi Pooja?', 'Yes. The Basic kit contains 11 clay diyas. The Standard kit adds 1 brass diya and 11 clay diyas. The Premium kit includes a large brass diya alongside 21 clay diyas and 175 cotton wicks, providing abundant light for multi-day Ganesh Chaturthi prayers.', 3)
ON CONFLICT (id) DO UPDATE SET answer = EXCLUDED.answer;
INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('8c60882d-ade5-53dc-9260-8ee8505ccce6', '79f27422-ef6a-5ebc-8e76-a66ecf6c9d06', 'Is a Red Chunari included in the Durga Pooja Kit?', 'Yes. The Basic kit includes a high-quality red Chunari with simple golden borders to drape over Maa Durga''s photo. The Standard and Premium kits upgrade this to a premium luxury Red Chunari decorated with elaborate gold zari and hand-embroidered lace borders.', 0)
