INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('e7d3b5ac-8288-5109-9595-f0c7372fedbc', 'c21ca8ed-8f4a-5fe2-8339-088ce2ae771f', 'What Rudraksha items are included in this kit?', 'The Basic kit includes an authentic, Varanasi-energized Rudraksha bead. The Standard kit includes a hand-knotted Rudraksha Japa Mala (108 beads). The Premium kit upgrades this to a premium hand-knotted Rudraksha Japa Mala alongside a large, selected Nepal Panchmukhi Rudraksha bead for altar worship.', 0)
