INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('0a54b451-dbca-5e4c-a924-3d84401e5c18', '39d3d451-a64a-53fb-b947-c10e6861fe8c', 'How do I know this Karungali Mala is original?', 'Authentic Karungali wood is dense, heavy, and naturally sinks in water due to its high density. It possesses a natural dark-brown to jet-black grain without artificial dye or chemical paint.', 0)
