INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('2a15f4a9-ab17-5dc6-9111-5c82801925d1', '39d3d451-a64a-53fb-b947-c10e6861fe8c', 'Can I wear the Karungali Mala daily or only use it for Japa?', 'You can both wear it around your neck for continuous aura protection or use it exclusively for mantra chanting.', 1)
