INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('6e410ace-dc08-52e8-9c52-eecb8fe59a75', 'ffca46be-7092-5f30-bc04-ab594a55be78', 'Who can wear or chant with 5 Mukhi Rudraksha Mala?', '5 Mukhi Rudraksha is universally auspicious and has no astrological side-effects. Anyone of any age, gender, or zodiac can wear it or use it for chanting.', 0)
