INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('16d8b257-5ac5-5248-bc7d-c0c8dfe03824', 'ffca46be-7092-5f30-bc04-ab594a55be78', 'How should I clean and maintain my Rudraksha mala?', 'Gently wash the beads once a month in clean water or Gangajal, let dry, and lightly condition with pure sandalwood or mustard oil.', 1)
