INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('74aaa550-6457-531f-9146-bc8287c62cf6', 'd6fc7d85-03ea-535e-8a51-a3c131bdc56d', 'Can Tulsi Mala be worn by everyone?', 'Yes, Tulsi Mala is pure and auspicious for all spiritual seekers. Traditionally, it is recommended to maintain a vegetarian diet when wearing it around the neck.', 0)
