INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('deece318-5829-5d0f-a01e-e014bdab0500', 'd6fc7d85-03ea-535e-8a51-a3c131bdc56d', 'Does genuine Tulsi wood have an aroma?', 'Original Tulsi wood possesses a subtle, natural herbal aroma that softens over time.', 1)
