INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('41b83083-98b8-506f-86ed-e5bbc159989b', '492dae22-9a4a-5556-888a-5094ca8355bd', 'How to test if Sphatik is real?', 'Real Sphatik stays naturally ice-cold even in hot weather, exhibits microscopic natural inclusions under strong light, and produces gentle sparks when rubbed in darkness.', 0)
