INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('9b4255c3-5e76-5f6a-b1d5-9fa39c41ec5c', '515dbae7-f705-5e19-a073-a2e385f5995d', 'Will the sandalwood aroma fade over time?', 'Authentic sandalwood contains essential oils deep inside the grain. Keeping the mala stored in its airtight pouch when not in use helps preserve its natural fragrance for years.', 0)
