INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('f2870b4e-51d2-5fde-bb07-ad61dfa7c238', '7ec53d33-c955-555c-bb57-0ea6b646e098', 'Why is Kamal Gatta Mala used for Lakshmi Puja?', 'Goddess Mahalakshmi is seated on a lotus (Kamal). Chanting her mantras on seeds born from the lotus flower aligns the mind with the frequency of pure abundance.', 0)
ON CONFLICT (id) DO UPDATE SET answer = EXCLUDED.answer;
INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('78cb38ec-0f5f-5444-a170-12e3cd05f0f0', '6a6c5e32-746e-5bdb-b9ca-4e21c133e957', 'What is the spiritual significance of Vaijayanti Mala?', 'Vaijayanti translates to ''that which brings victory''. Lord Krishna wore the Vaijayanti garland in Vrindavan, symbolizing divine victory over ego and ignorance.', 0)
ON CONFLICT (id) DO UPDATE SET answer = EXCLUDED.answer;
INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('a2226863-f174-5e86-bcd4-68f337e4d0e8', '54958822-ae8a-5dd6-80d0-077958c60671', 'How does pearl mala help astrologically?', 'Pearl is the primary gemstone of the Moon (Chandra). When Chandra is weak or afflicted in the birth chart, wearing or meditating with a pearl mala restores emotional calm.', 0)
ON CONFLICT (id) DO UPDATE SET answer = EXCLUDED.answer;
INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('e3a964a6-4530-5cfa-9ffc-6867bd12e1e8', '9f67c01f-1be3-5133-b98b-f279509b2ad1', 'What is the benefit of chanting Hanuman mantras on Red Coral Mala?', 'Red Coral vibrates with the fiery energy of Mars (Mangal), the planetary ruler aligned with Lord Hanuman. Chanting Hanuman Chalisa on Moonga mala multiplies protective strength.', 0)
ON CONFLICT (id) DO UPDATE SET answer = EXCLUDED.answer;
INSERT INTO public.product_faqs (id, product_id, question, answer, display_order)
VALUES ('2e8fdb9e-0882-5340-b597-7967648c695c', '3a3ee5e4-6692-5532-968f-2cdcdd4aae14', 'Why choose a Big Size Rudraksha Mala?', 'The large 12mm beads give a substantial, heavy feel in the hand, making it easier to count mantras during long meditation sessions without fingers slipping.', 0)
ON CONFLICT (id) DO UPDATE SET answer = EXCLUDED.answer;

